def reset(self,command:ResetCharacterCommand)->CharacterCommandResult:
  with self._unit_of_work_factory() as unit:
   current=unit.characters.find_by_id(command.character_id)
   if current is None:return CharacterCommandResult(CharacterResultStatus.NOT_FOUND,"character_not_found",None)
   # V1 DEV reset clears name and class; deleting the V2 character aggregate returns the account to registration.
   unit.characters.delete(command.character_id);unit.commit()
  return CharacterCommandResult(CharacterResultStatus.RESET,"character_reset_requires_registration",None)

def recover_persisted_encounters_after_restart(markers: Iterable[PersistedEncounterMarker], now: datetime) -> tuple[EncounterPersistenceResult, ...]:
    """Apply V1-equivalent stale expiry/cleanup, never exact battle resumption."""
    return tuple(expire_persisted_encounter_once(marker, now) for marker in select_expired_persisted_encounters(markers, now))

def delete(self, key: K) -> None:
        if not self.transaction_active:
            raise RuntimeError("sandbox_transaction_required")
        self._items.pop(key, None)

def _delete_v2_database_files(self) -> None:
        """Delete only V2 DB sidecars; V1 game.db WAL/SHM are outside this ownership boundary."""
        for suffix in ("", "-wal", "-shm", "-journal"):
            candidate = Path(f"{self._database_path}{suffix}")
            candidate.unlink(missing_ok=True)

